try:
    print('>>> x = 2.3456')
    print('>>> y = 1j')
    print('>>> x -= y')
    print('>>> x')
    x = 2.3456
    y = 1j
    x -= y
    print(x)
except Exception as e:
    print(type(e), ':', e)
print()
